#!/usr/bin/env node
// pnpm run sync-brand [--check]
//
// Copies the brand files the site uses from docs/brand/ (generated by docs/brand/render.py;
// never redraw them) into public/brand/, where they are tracked. With --check it only
// reports copies that differ and exits 1 (a test does the same).
//
// tau-coin-ember.svg is the one derived file: tau-coin.svg drawn in Ember instead of
// `currentColor`, which an <img> or a favicon would render black.

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = join(root, "..", "..", "docs", "brand");
const target = join(root, "public", "brand");
const check = process.argv.includes("--check");

export const COPIED = [
  "tau-hero.svg",
  "tau-lockup-dark.svg",
  "tau-mark.svg",
  "tau-app-icon.svg",
  "tau-coin.svg",
];
const EMBER = "#FF7A3D";

/** @type {Record<string, string>} */
const wanted = {};
for (const name of COPIED) wanted[name] = readFileSync(join(source, name), "utf8");
wanted["tau-coin-ember.svg"] = wanted["tau-coin.svg"].replaceAll("currentColor", EMBER);

const stale = [];
for (const [name, text] of Object.entries(wanted)) {
  const path = join(target, name);
  const current = existsSync(path) ? readFileSync(path, "utf8") : null;
  if (current === text) continue;
  stale.push(name);
  if (!check) writeFileSync(path, text);
}

if (check) {
  if (stale.length > 0) {
    console.error(
      `Out of date in public/brand/: ${stale.join(", ")}. Run \`pnpm run sync-brand\`.`,
    );
    process.exit(1);
  }
  console.log("public/brand/ matches docs/brand/.");
} else {
  console.log(
    stale.length > 0
      ? `Updated public/brand/: ${stale.join(", ")}.`
      : "public/brand/ is up to date.",
  );
}
